mapper.select:
SELECT d.id AS draft_id, coalesce(nullif(tv.title,''), nullif(d.output #>> '{theme,title}',''), nullif(d.input ->> 'topic',''),'테마 초안') AS title, CASE WHEN tv.id IS NOT NULL THEN tv.intro_image_uri ELSE intro.output #>> '{images,INTRO}' END AS thumbnail_url, d.grade, d.source, d.status, AS stage, d.week_start, AS applied_week, CASE WHEN d.status IN ('DISCARDED','ADOPTED') THEN d.planned_week ELSE owner.planned_week END AS planned_week, d.updated_at, d.theme_id, pending.scene AS comparison_scene
LEFT JOIN weekly_theme_version tv ON tv.id=CASE WHEN t.status='PUBLISHED' THEN t.published_version_id ELSE t.current_version_id END LEFT JOIN theme_draft_scene_selection choice ON choice.root_id=coalesce(d.family_root_id,d.id) AND choice.scene='INTRO' LEFT JOIN theme_draft intro ON intro.id=coalesce(CASE WHEN d.status IN ('ADOPTED','DISCARDED') THEN (d.frozen_scene_choices->>'INTRO')::uuid ELSE choice.version_id END,d.id)
ORDER BY d.updated_atd.created_at DESC, d.id LIMIT #{size} OFFSET #{offset}

SELECT  FROM theme_draft

ORDER BY created_at DESC, id
LIMIT #{size} OFFSET #{offset}

SELECT input FROM theme_draft
WHERE grade = #{grade} AND week_start >= #{from} AND week_start < #{until}
ORDER BY created_at
